-- Cancelled history only; current values, retries, successful exports and undo data are preserved.
set local lock_timeout = '2s';
set local statement_timeout = '30s';

create or replace function operations_private.prune_operations_hub_cancelled_history_v1()
returns jsonb
language plpgsql
security invoker
set search_path = pg_catalog
set lock_timeout = '2s'
set statement_timeout = '30s'
as $function$
declare
  v_cutoff timestamptz := statement_timestamp() - interval '30 days';
  v_ids bigint[];
  v_deleted integer := 0;
  v_events integer := 0;
begin
  -- Serialize overlapping manual/cron invocations without waiting.
  if not pg_try_advisory_xact_lock(60908, 30) then
    return jsonb_build_object('skipped', 'already_running', 'cancelled_changes_removed', 0, 'change_events_removed', 0);
  end if;

  select array_agg(candidate.change_id) into v_ids
  from (
    select q.change_id
    from public.operations_hub_change_queue q
    where q.status = 'cancelled'
      and greatest(q.updated_at, q.cancelled_at, q.requested_at) < v_cutoff
      -- Preserve every export reference, including cancelled/failed export evidence.
      and not exists (select 1 from public.operations_hub_export_items e where e.change_id = q.change_id)
      -- An earlier successful export remains protected even if its export item is absent.
      and not exists (select 1 from public.operations_hub_change_events e
        where e.change_id = q.change_id and (e.event_type = 'exported' or e.created_at >= v_cutoff))
      -- Do not partially prune a batch that still contains live/saved changes.
      and not exists (select 1 from public.operations_hub_change_queue sibling
        where sibling.change_batch_id = q.change_batch_id and sibling.status <> 'cancelled')
    order by q.change_id
    limit 1000
    for update of q skip locked
  ) candidate;

  if coalesce(cardinality(v_ids), 0) > 0 then
    select count(*) into v_events from public.operations_hub_change_events where change_id = any(v_ids);
    -- Existing FK cascades ONLY these cancelled changes' events.
    -- Export items are never deleted or detached by this retention function.
    delete from public.operations_hub_change_queue where change_id = any(v_ids) and status = 'cancelled';
    get diagnostics v_deleted = row_count;
  end if;
  return jsonb_build_object('retention_days', 30, 'batch_limit', 1000,
    'cancelled_changes_removed', v_deleted, 'change_events_removed', v_events,
    'cutoff', v_cutoff, 'completed_at', clock_timestamp());
end;
$function$;
revoke all on function operations_private.prune_operations_hub_cancelled_history_v1() from public, anon, authenticated;

create or replace function operations_private.prune_operations_hub_history()
returns jsonb
language plpgsql
security invoker
set search_path = pg_catalog
set lock_timeout = '2s'
set statement_timeout = '30s'
as $function$
declare
  v_snapshot_rows integer := 0;
  v_cron_rows integer := 0;
  v_cancelled jsonb;
begin
  with ranked_ready as (
    select snapshot_id, row_number() over (order by created_at desc, snapshot_id desc) as snapshot_rank
    from public.sellpia_stock_snapshots where upload_status = 'ready'
  ), deleted as (
    delete from public.sellpia_stock_snapshots s using ranked_ready r
    where s.snapshot_id = r.snapshot_id and r.snapshot_rank > 2 returning s.snapshot_id
  ) select count(*) into v_snapshot_rows from deleted;

  with deleted as (
    delete from cron.job_run_details where end_time < now() - interval '7 days' returning runid
  ) select count(*) into v_cron_rows from deleted;

  v_cancelled := operations_private.prune_operations_hub_cancelled_history_v1();
  return jsonb_build_object('ready_snapshots_removed', v_snapshot_rows,
    'cron_job_runs_removed', v_cron_rows, 'cancelled_history', v_cancelled,
    'completed_at', clock_timestamp());
end;
$function$;
revoke all on function operations_private.prune_operations_hub_history() from public, anon, authenticated;

-- Earlier vacuum/analyze makes freed pages reusable before large update batches accumulate.
-- This does not schedule blocking CLUSTER/REINDEX in daily production jobs.
alter table public.operations_hub_change_queue set (
  autovacuum_vacuum_scale_factor = 0.05, autovacuum_vacuum_threshold = 50,
  autovacuum_analyze_scale_factor = 0.02, autovacuum_analyze_threshold = 50);
alter table public.operations_hub_change_events set (
  autovacuum_vacuum_scale_factor = 0.05, autovacuum_vacuum_threshold = 50,
  autovacuum_analyze_scale_factor = 0.02, autovacuum_analyze_threshold = 50);
alter table public.operations_hub_export_items set (
  autovacuum_vacuum_scale_factor = 0.05, autovacuum_vacuum_threshold = 50,
  autovacuum_analyze_scale_factor = 0.02, autovacuum_analyze_threshold = 50);
-- Existing 03:23 KST job calls the updated function; preserve its schedule and active state.
